INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2452, 'ក្នុងការ៉េ \(100\) ផាត់ពណ៌ \(30\)។ ការ៉េផាត់ពណ៌ជាប៉ុន្មានភាគរយ?', NULL, '["\\(30\\%\\)", "\\(70\\%\\)", "\\(0.3\\%\\)", "\\(3\\%\\)"]', 0, NULL, 1, 'mcq', 'ភាគរយជាចំនួនក្នុងមួយរយ។', 'ភាគរយ', 'easy', 1, '7', 'ភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2453, 'សរសេរ \(70\%\) ជាប្រភាគដែលមិនអាចសម្រួលបាន៖', NULL, '["\\(\\dfrac{7}{10}\\)", "\\(\\dfrac{1}{70}\\)", "\\(\\dfrac{4}{5}\\)", "\\(\\dfrac{7}{5}\\)"]', 0, NULL, 1, 'mcq', '\(70\% = \dfrac{70}{100} = \dfrac{7}{10}\)។', 'ភាគរយ', 'easy', 1, '7', 'ភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2454, 'គ្រូបង្រៀន \(70\) នាក់ ក្នុងនោះ \(56\) នាក់ជាអ្នកគ្រូ។ ភាគរយអ្នកគ្រូគឺ៖', NULL, '["\\(20\\%\\)", "\\(70\\%\\)", "\\(80\\%\\)", "\\(56\\%\\)"]', 2, NULL, 1, 'mcq', '\(\dfrac{56}{70} \times 100 = 80\)។', 'ភាគរយ', 'easy', 1, '7', 'ភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2455, 'តុមួយថ្លៃ \(80\,000\) ៛ បញ្ចុះតម្លៃ \(15\%\)។ ការបញ្ចុះតម្លៃជាប៉ុន្មានរៀល?', NULL, '["\\(12\\,000\\) ៛", "\\(68\\,000\\) ៛", "\\(15\\,000\\) ៛", "\\(65\\,000\\) ៛"]', 0, NULL, 1, 'mcq', '\(80\,000 \times 0.15 = 12\,000\)។', 'ភាគរយ', 'easy', 1, '7', 'ភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2456, '\(25\%\) អានថា៖', NULL, '["ម្ភៃប្រាំភាគរយ", "ម្ភៃប្រាំរយ", "ម្ភៃប្រាំភាគមួយរយប្រាំ", "ម្ភៃប្រាំភាគដប់"]', 0, NULL, 1, 'mcq', '\(25\% = \dfrac{25}{100}\)។', 'ភាគរយ', 'easy', 1, '7', 'ភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2457, 'សរសេរ \(35\%\) ជាប្រភាគដែលមិនអាចសម្រួលបាន៖', NULL, '["\\(\\dfrac{1}{35}\\)", "\\(\\dfrac{7}{10}\\)", "\\(\\dfrac{7}{20}\\)", "\\(\\dfrac{9}{20}\\)"]', 2, NULL, 2, 'mcq', '\(35\% = \dfrac{35}{100} = \dfrac{7}{20}\)។', 'ភាគរយ', 'medium', 1, '7', 'ភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2458, 'សិស្សម្នាក់ទទួលពិន្ទុ \(42\) ក្នុង \(70\) ពិន្ទុរូបវិទ្យា និង \(36\) ក្នុង \(50\) ភូមិវិទ្យា។ មុខវិជ្ជាណាបានភាគរយខ្ពស់ជាង?', NULL, '["ភូមិវិទ្យា \\(60\\%\\)", "ភូមិវិទ្យា \\(72\\%\\)", "រូបវិទ្យា \\(60\\%\\)", "ស្មើគ្នា"]', 1, NULL, 2, 'mcq', '\(\dfrac{42}{70} = 60\%\) \(\dfrac{36}{50} = 72\%\)។', 'ភាគរយ', 'medium', 1, '7', 'ភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2459, 'ទិញទំនិញមួយថ្លៃ \(112\,000\) ៛ ហើយលក់វិញ \(140\,000\) ៛។ ភាគរយប្រាក់ចំណេញគឺ៖', NULL, '["\\(30\\%\\) ចំណេញ", "\\(20\\%\\) ចំណេញ", "\\(25\\%\\) ចំណេញ", "\\(25\\%\\) ខាត"]', 2, NULL, 2, 'mcq', 'ភាគរយ ចំណេញ \(= \dfrac{|\text{លក់} - \text{ដើម}|}{\text{ដើម}} \times 100 = 25\%\)។', 'ភាគរយ', 'medium', 1, '7', 'ភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2460, 'តុមួយថ្លៃ \(80\,000\) ៛ បញ្ចុះតម្លៃ \(15\%\)។ ថ្លៃលក់ក្រោយបញ្ចុះគឺ៖', NULL, '["\\(92\\,000\\) ៛", "\\(12\\,000\\) ៛", "\\(68\\,000\\) ៛", "\\(65\\,000\\) ៛"]', 2, NULL, 2, 'mcq', '\(80\,000 - 12\,000 = 68\,000\)។', 'ភាគរយ', 'medium', 1, '7', 'ភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2461, 'ខ្ចីប្រាក់ \(400\,000\) ៛ អត្រា \(6\%\) មួយឆ្នាំ រយៈពេល \(3\) ឆ្នាំ។ ការប្រាក់សរុបគឺ៖', NULL, '["\\(472\\,000\\) ៛", "\\(24\\,000\\) ៛", "\\(72\\,000\\) ៛", "\\(7\\,200\\) ៛"]', 2, NULL, 2, 'mcq', '\(I = 400\,000 \times 0.06 \times 3 = 72\,000\)។', 'ភាគរយ', 'medium', 1, '7', 'ភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2462, 'ភ្នាក់ងារលក់ដីបាន \(8\,800\,000\) ៛ ទទួលកម្រៃជើងសា \(3\%\)។ កម្រៃជើងសាស្មើប៉ុន្មាន?', NULL, '["\\(2\\,640\\,000\\) ៛", "\\(8\\,536\\,000\\) ៛", "\\(26\\,400\\) ៛", "\\(264\\,000\\) ៛"]', 3, NULL, 2, 'mcq', '\(8\,800\,000 \times 0.03 = 264\,000\)។', 'ភាគរយ', 'medium', 1, '7', 'ភាគរយ', NULL, 0);
