INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2469, 'អាជីវករទិញមាន់ \(10\) kg ថ្លៃ \(180\,000\) ៛ លក់ក្នុង \(12\,500\) ៛/kg។ ចំណេញឬខាត? ភាគរយប៉ុន្មាន?', NULL, '["ចំណេញ \\(30.6\\%\\)", "ខាត \\(44\\%\\)", "ខាត \\(30.6\\%\\)", "ខាត \\(55\\%\\)"]', 2, NULL, 3, 'mcq', 'ថ្លៃលក់ \(125\,000\) ខាត \(55\,000\) \(\dfrac{55}{180} \approx 30.6\%\)។', 'ភាគរយ', 'pisa', 1, '7', 'ភាគរយ', NULL, 0);
