INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2472, 'ហ៊ានតុងលក់នាឡិកាមួយ \(260\,000\) ៛ ចំណេញ \(30\%\) លើថ្លៃដើម។ រកថ្លៃដើម និងប្រាក់ចំណេញ។', NULL, '[]', 0, NULL, 5, 'writing', 'ថ្លៃលក់ \(= 130\%\) នៃថ្លៃដើម (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2473, 'ទូរទស្សន៍មួយតម្លៃធម្មតា \(640\,000\) ៛ លក់បញ្ចុះមកត្រឹម \(560\,000\) ៛។ គណនាអត្រាបញ្ចុះតម្លៃ។', NULL, '[]', 0, NULL, 5, 'writing', 'ការបញ្ចុះ \(640\,000 - 560\,000 = 80\,000\) ៛ (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2474, 'ម៉ីងសំបញ្ញើប្រាក់ \(1\,450\,000\) ៛ អត្រា \(10\%\) ក្នុងមួយឆ្នាំ រយៈពេល \(1\) ឆ្នាំ \(3\) ខែ។ គណនាការប្រាក់ និងប្រាក់សរុបដែលនាងទទួលបាន។', NULL, '[]', 0, NULL, 5, 'writing', 'រយៈពេល \(1\ \text{ឆ្នាំ}\ 3\ \text{ខែ} = 1.25\) ឆ្នាំ (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2475, 'ហាងមួយទិញកង្ហារ \(10\) គ្រឿង ថ្លៃសរុប \(600\,000\) ៛។ លក់អស់ ខាត \(5\,000\) ៛ ក្នុងមួយគ្រឿង។ ក. ថ្លៃលក់មួយគ្រឿង? ខ. អត្រាប្រាក់ខាត? គ. ខាតសរុបប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ថ្លៃដើមមួយគ្រឿង \(600\,000 \div 10 = 60\,000\) ថ្លៃលក់ \(60\,000 - 5\,000 = 55\,000\) ៛ (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2476, 'សុខជាបុគ្គលិកលក់ឧបករណ៍អេឡិចត្រូនិក ទទួលប្រាក់ខែ \(600\,000\) ៛ បូកកម្រៃជើងសា \(2.5\%\) លើទំនិញលក់បាន។ ខែនេះលក់បាន \(12\,000\,000\) ៛។ ក. គណនាកម្រៃជើងសា។ ខ. ចំណូលសរុបក្នុងខែ។ គ. កម្រៃជើងសាជាប៉ុន្មានភាគរយនៃចំណូលសរុប?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(12\,000\,000 \times 0.025 = 300\,000\) ៛ (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2477, 'ហាងលក់ខោអាវ ៖ ខោមួយថ្លៃ \(38\,000\) ៛ ក្រោយមួយខែបញ្ចុះមក \(30\,000\) ៛។ ក. អត្រាបញ្ចុះតម្លៃ? ខ. បើទិញខោ \(5\) ដុំ ក្រោយបញ្ចុះ សន្សំបានប៉ុន្មានរៀល? គ. ហាងបានលក់ \(200\) ដុំ ក្រោយបញ្ចុះ ទទួលចំណូលប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{8\,000}{38\,000} \times 100 \approx 21.05\%\) (2 ពិន្ទុ)
